<?php

declare(strict_types=1);

namespace App\ApiAdmin\MCP\Tools;

use App\ApiAdmin\MCP\AtomicFileWriter;
use App\ApiAdmin\MCP\ServiceRegistry;
use Illuminate\Support\Facades\Artisan;
use Illuminate\Support\Facades\File;
use Illuminate\Support\Facades\Log;
use Illuminate\Support\Str;
use InvalidArgumentException;
use Throwable;

/**
 * MCP Tool: configure_layout
 *
 * Customizes a panel's layout: logos and title. Menu items come from the panel's resources.
 * Modifies the existing layout PHP file generated by register_service.
 */
final class ConfigureLayoutTool implements ToolContract
{
    /**
     * MCP tool schema definition.
     *
     * @return array<string, mixed>
     */
    public static function schema(): array
    {
        return [
            'name' => 'configure_layout',
            'description' => 'Generation changes are serialized and rolled back on failure. Customize panel layout: logo, title. Menu items are auto-discovered from resources belonging to the panel.',
            'inputSchema' => [
                'type' => 'object',
                'properties' => [
                    'service' => [
                        'type' => 'string',
                        'description' => 'Service name whose layout to configure',
                    ],
                    'logo' => [
                        'type' => 'string',
                        'description' => 'Logo image path, stored as a literal string',
                    ],
                    'logo_small' => [
                        'type' => 'string',
                        'description' => 'Small logo image path, stored as a literal string',
                    ],
                    'title' => [
                        'type' => 'string',
                        'description' => 'Panel title override',
                    ],
                ],
                'required' => ['service'],
            ],
        ];
    }

    /**
     * Execute the configure_layout tool.
     *
     * @param  array{
     *     service: string,
     *     logo?: string,
     *     logo_small?: string,
     *     title?: string,
     * }  $params
     *
     * @return array<string, mixed>
     */
    public function execute(array $params): array
    {
        $serviceName = $params['service'];
        if (preg_match('/^[A-Za-z_][A-Za-z0-9_-]*$/D', $serviceName) !== 1) {
            return ['success' => false, 'code' => 'VALIDATION', 'error' => 'Invalid service identifier.'];
        }
        $className = Str::studly($serviceName).'Layout';

        Log::info('ConfigureLayoutTool: executing', [
            'service' => $serviceName,
            'has_logo' => isset($params['logo']),
        ]);

        $layoutsPath = (new ServiceRegistry)->layoutsPath();
        $filePath = $layoutsPath.'/'.$className.'.php';

        if (! File::exists($filePath)) {
            Log::error('ConfigureLayoutTool: layout file not found', [
                'file' => $filePath,
            ]);

            return [
                'success' => false,
                'error' => "Layout file not found: {$filePath}. Run register_service for '{$serviceName}' first.",
            ];
        }

        $content = File::get($filePath);
        $changes = [];

        // Update logo
        if (isset($params['logo'])) {
            $content = $this->updateLogo($content, $params['logo']);
            $changes[] = 'logo';
        }

        // Update small logo
        if (isset($params['logo_small'])) {
            $content = $this->updateLogoSmall($content, $params['logo_small']);
            $changes[] = 'logo_small';
        }

        if (isset($params['title'])) {
            $this->updateTitle($serviceName, $params['title']);
            $changes[] = 'title';
        }

        if (isset($params['logo']) || isset($params['logo_small'])) {
            AtomicFileWriter::put($filePath, $content);
        }

        // Trigger hot-reload
        try {
            Artisan::call('api-admin:reload');
        } catch (Throwable $e) {
            Log::warning('ConfigureLayoutTool: reload failed (non-blocking)', [
                'error' => $e->getMessage(),
            ]);
        }

        Log::info('Completed', [
            'file' => $filePath,
            'changes' => $changes,
        ]);

        return [
            'success' => true,
            'file' => $filePath,
            'changes' => $changes,
            'message' => "Layout '{$className}' updated: ".implode(', ', $changes),
        ];
    }

    /**
     * Update the getLogo() method return value.
     */
    private function updateLogo(string $content, string $logo, bool $small = false): string
    {
        $literal = "'(?:[^'\\\\]|\\\\.)*'";
        $updated = preg_replace_callback(
            '~(function getLogo\(bool \$small = false\): string\s*\{\s*return \$small\s*\?\s*)('.$literal.')(\s*:\s*)('.$literal.')(\s*;)~s',
            static fn (array $matches): string => $matches[1]
                .($small ? var_export($logo, true) : $matches[2])
                .$matches[3]
                .($small ? $matches[4] : var_export($logo, true))
                .$matches[5],
            $content,
            count: $count,
        );
        if ($count === 0) {
            $method = $small ? 'getLogoSmall' : 'getLogo';
            $updated = preg_replace_callback(
                '/(function '.$method.'\(\): string\s*\{\s*return )'.$literal.'\s*;/s',
                static fn (array $matches): string => $matches[1].var_export($logo, true).';',
                $content,
                count: $count,
            );
        }
        if ($updated === null || $count !== 1) {
            throw new InvalidArgumentException('Unsupported layout logo method. Regenerate the layout with register_service.');
        }

        return $updated;
    }

    private function updateLogoSmall(string $content, string $logoSmall): string
    {
        return $this->updateLogo($content, $logoSmall, small: true);
    }

    private function updateTitle(string $service, string $title): void
    {
        $servicesPath = config('api-admin.generated_services_path');
        $services = is_string($servicesPath) && is_file($servicesPath) ? include $servicesPath : [];
        $services = is_array($services) && is_array($services['services'] ?? null)
            ? $services['services']
            : config('api-admin.services', []);
        $serviceConfig = is_array($services) ? ($services[$service] ?? null) : null;
        $panel = is_array($serviceConfig) ? ($serviceConfig['panel'] ?? null) : null;
        $panelsPath = config('api-admin.generated_panels_path');
        if (! is_string($panel) || ! is_string($panelsPath) || ! is_file($panelsPath)) {
            throw new InvalidArgumentException('Generated panel not found. Run register_service first.');
        }
        if (function_exists('opcache_invalidate')) {
            opcache_invalidate($panelsPath, true);
        }
        $panels = include $panelsPath;
        if (! is_array($panels) || ! is_array($panels[$panel] ?? null)) {
            throw new InvalidArgumentException('Generated panel not found. Run register_service first.');
        }
        $panels[$panel]['title'] = $title;
        AtomicFileWriter::put($panelsPath, "<?php\n\ndeclare(strict_types=1);\n\nreturn ".var_export($panels, true).";\n");
        $current = config('moonshine.panels', []);
        $panels = array_replace(is_array($current) ? $current : [], $panels);
        config(['moonshine.panels' => $panels]);
    }
}
